 CREATE TEMPORARY TABLE rrc223_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc223_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc223_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
